226	    private static String normalizeEmail(String email) {
227	        if (email == null || email.isBlank()) {
228	            return null;
229	        }
230	        String trimmed = email.trim();
231	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
232	            throw new InvalidEmailException("Email must be a syntactically valid address");
233	        }
234	        return trimmed.toLowerCase(Locale.ROOT);
235	    }
236	
237	    /**
238	     * Rejects a create whose E.164 telephone is already used by any existing owner, so that
239	     * telephones stay unique across owners. Telephones are stored in E.164 form on create, so a
240	     * direct equality comparison of the E.164 values against the stored values is sufficient.
241	     *
242	     * @param normalizedTelephone the E.164 telephone of the owner being created
243	     * @throws DuplicateTelephoneException if another owner already uses this telephone
244	     */
245	    private void rejectDuplicateTelephone(String normalizedTelephone) {
246	        boolean inUse = this.clinicService.findAllOwners().stream()
247	            .anyMatch(existing -> normalizedTelephone.equals(existing.getTelephone()));
248	        if (inUse) {
249	            throw new DuplicateTelephoneException(
250	                "Telephone is already used by another owner");
251	        }
252	    }
253	
254	    /**
255	     * Rejects a create that would place the owner in a household already occupied by another owner,
256	     * i.e. one whose last name and address match the supplied values. The two fields are compared
257	     * case-insensitively after whitespace is collapsed (leading/trailing whitespace trimmed and each
